type DeviceDraft = { name:string; role:'Spine'|'Leaf'|'Border' };
type LinkDraft = { source:string; target:string };
type DeviceAssignments = Record<string,string>;
type EvidenceDecision = 'new'|'accepted'|'accepted-unassigned';
type UseCase = 'aidc'|'idc'|'campus';
type StudioRequirement = 'Recommended'|'Optional';
type StudioRule = { studioId:string; defaultSelected:boolean; reason:string };
type SolutionProfile = { label:string; shortLabel:string; referenceLabel:string; description:string; rules:StudioRule[] };
type PlanStudio = CatalogStudio & { group:string; featured:boolean; requirement:StudioRequirement; reason:string; effectiveScope:string; estimatedContribution:string };
type ConfigLineState = 'same'|'added'|'modified'|'removed';
type ConfigPreviewLine = { id:string; designed:string; running:string; state:ConfigLineState; source:string };
type ConfigPreviewDevice = { id:string; hostname:string; plannedNode:string; role:string; model:string; lines:ConfigPreviewLine[]; sources:string[] };
type GuidedTopologyState = { nodes:TopologyNode<DesignNode>[]; links:TopologyLink[]; removedBaselineLinkIds:string[] };
type FabricDesign = { id:string; name:string; description:string; useCase:UseCase; referenceDesign:string; type:string; topology:string; pods:number; spines:number; leafs:number; borders:number; devices:number; alignment:string; deploymentStatus:'Deployed'|'Pending Changes'|'Partially Deployed'; lastModified:string; revision:number; workspaceId:string; isInitialDraft?:boolean; guidedTopology?:GuidedTopologyState };
type ActiveDesign = { id: string; isInitialDraft: boolean };
type CreateDesignDraft = { name:string; description:string; useCase:UseCase; referenceDesign:string };

